@sig trait ProductionOutcomeDeterminer_Api {
  def id: Art.BridgeId
  def outcomeFact_Id : Art.PortId
  def appliedSnapshot_Id : Art.PortId
  def productionOutcome_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var productionOutcome: Factory_Flow.ProductionOutcome = $

  def put_productionOutcome(value : Factory_Flow.ProductionOutcome) : Unit = {
    Contract(
      Modifies(productionOutcome),
      Ensures(
        productionOutcome == value
      )
    )
    Spec {
      productionOutcome = value
    }

    Art.putValue(productionOutcome_Id, Factory_Flow.ProductionOutcome_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ProductionOutcomeDeterminer_Initialization_Api (
  val id: Art.BridgeId,
  val outcomeFact_Id : Art.PortId,
  val appliedSnapshot_Id : Art.PortId,
  val productionOutcome_Id : Art.PortId) extends ProductionOutcomeDeterminer_Api

@datatype class ProductionOutcomeDeterminer_Operational_Api (
  val id: Art.BridgeId,
  val outcomeFact_Id : Art.PortId,
  val appliedSnapshot_Id : Art.PortId,
  val productionOutcome_Id : Art.PortId) extends ProductionOutcomeDeterminer_Api {

  // Logika spec var representing port state for incoming data port
  @spec var outcomeFact: Factory_Flow.OutcomeFact = $

  def get_outcomeFact() : Option[Factory_Flow.OutcomeFact] = {
    Contract(
      Ensures(
        Res == Some(outcomeFact)
      )
    )
    val value : Option[Factory_Flow.OutcomeFact] = Art.getValue(outcomeFact_Id) match {
      case Some(Factory_Flow.OutcomeFact_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port outcomeFact.  Expecting 'Factory_Flow.OutcomeFact_Payload' but received ${v}")
        None[Factory_Flow.OutcomeFact]()
      case _ => None[Factory_Flow.OutcomeFact]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var appliedSnapshot: Factory_Flow.FlowSnapshot = $

  def get_appliedSnapshot() : Option[Factory_Flow.FlowSnapshot] = {
    Contract(
      Ensures(
        Res == Some(appliedSnapshot)
      )
    )
    val value : Option[Factory_Flow.FlowSnapshot] = Art.getValue(appliedSnapshot_Id) match {
      case Some(Factory_Flow.FlowSnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port appliedSnapshot.  Expecting 'Factory_Flow.FlowSnapshot_Payload' but received ${v}")
        None[Factory_Flow.FlowSnapshot]()
      case _ => None[Factory_Flow.FlowSnapshot]()
    }
    return value
  }
}
